48	        jdbc.update("DELETE FROM approval");
49	        jdbc.update("DELETE FROM recall");
50	        jdbc.update("DELETE FROM test_result");
51	        jdbc.update("DELETE FROM batch_required_test");
52	        jdbc.update("DELETE FROM batch_lineage");
53	        jdbc.update("DELETE FROM batch");
54	    }
55	
56	    // ---------- 主流程 ----------
57	
58	    @Test
59	    void happyFlow_quarantineToReleasedThenRecalled() throws Exception {
60	        String batchKey = "BK-HAPPY-" + unique();
61	        createBatch(batchKey, List.of("外观", "含量", "无菌"), 201);
62	
63	        // 初始隔离，出现在可用列表
64	        assertEquals("QUARANTINED", currentStatus(batchKey));
65	        assertTrue(availableKeys().contains(batchKey));
66	
67	        submitTest(batchKey, testReq("TK-1", "外观", "PASS", "inspect-a"), null, null, 201);
68	        assertEquals("QUARANTINED", currentStatus(batchKey));
69	        submitTest(batchKey, testReq("TK-2", "含量", "PASS", "inspect-b"), null, null, 201);
70	        assertEquals("QUARANTINED", currentStatus(batchKey));
71	        submitTest(batchKey, testReq("TK-3", "无菌", "PASS", "inspect-c"), null, null, 201);
72	        assertEquals("PENDING_RELEASE", currentStatus(batchKey));
73	
74	        approve(batchKey, "qa-1", "QUALITY", "CK-AP-1", 201);
75	        assertEquals("RELEASE_REVIEW", currentStatus(batchKey));
76	        approve(batchKey, "ops-1", "OPERATIONS", "CK-AP-2", 201);
77	        assertEquals("RELEASED", currentStatus(batchKey));
78	
79	        // 召回：立即离开可用列表，但历史完整保留
80	        recall(batchKey, "any-user", "客户投诉，疑似污染", "CK-RC-1", 201);
81	        assertEquals("RECALLED", currentStatus(batchKey));
82	        assertFalse(availableKeys().contains(batchKey));
83	
84	        MvcResult historyResult = mockMvc.perform(get("/api/batches/" + batchKey + "/history"))
85	                .andExpect(status().isOk()).andReturn();
86	        JsonNode history = objectMapper.readTree(historyResult.getResponse().getContentAsString());
87	        assertEquals(3, history.path("tests").size());
88	        assertEquals(2, history.path("approvals").size());
89	        assertEquals("RECALLED", history.path("batch").path("status").asText());
90	        assertEquals("客户投诉，疑似污染", history.path("recall").path("reason").asText());
91	        assertEquals("RELEASED", history.path("approvals").get(1).path("batchStatus").asText());
92	    }
93	
94	    // ---------- 失败分支 ----------
95	
96	    @Test
97	    void anyFail_immediatelyRejected_andBlocksTestsApprovalsAndRecall() throws Exception {
98	        String batchKey = "BK-FAIL-" + unique();
99	        createBatch(batchKey, List.of("t1", "t2"), 201);
100	        submitTest(batchKey, testReq("TK-F", "t1", "FAIL", "insp-1"), null, null, 201);
101	        assertEquals("REJECTED", currentStatus(batchKey));
102	
103	        // 已拒绝不能再检验、不能批准、不能召回（召回仅针对 RELEASED）
104	        submitTest(batchKey, testReq("TK-P", "t2", "PASS", "insp-2"), null, null, 409);
105	        approve(batchKey, "qa-9", "QUALITY", "CK-A", 409);
106	        recall(batchKey, "u", "r", "CK-R", 409);
107	        // REJECTED 批次仍在当前列表中（只有召回才从可用列表移除）
108	        assertTrue(availableKeys().contains(batchKey));
109	    }
110	
111	    @Test
112	    void unknownTestItem_returns422() throws Exception {
113	        String batchKey = "BK-BADITEM-" + unique();
114	        createBatch(batchKey, List.of("t1"), 201);
115	        submitTest(batchKey, testReq("TK-X", "不存在的项目", "PASS", "i"), null, null, 422);
116	        assertEquals("QUARANTINED", currentStatus(batchKey));
117	    }
118	
119	    @Test
120	    void approveBeforeAllTestsPassed_returns422() throws Exception {
121	        String batchKey = "BK-EARLY-" + unique();
122	        createBatch(batchKey, List.of("t1", "t2"), 201);
123	        submitTest(batchKey, testReq("TK-1", "t1", "PASS", "insp"), null, null, 201);
124	        approve(batchKey, "qa-1", "QUALITY", "CK-A", 422);
125	        assertEquals("QUARANTINED", currentStatus(batchKey));
126	    }
127	
128	    @Test
129	    void approvalConstraints_duplicateRole_sameActor_inspectorRejected() throws Exception {
130	        String batchKey = "BK-CONSTRAINT-" + unique();
131	        createBatch(batchKey, List.of("t1"), 201);
132	        submitTest(batchKey, testReq("TK-1", "t1", "PASS", "inspector-1"), null, null, 201);
133	
134	        // 检验人不能批准
135	        approve(batchKey, "inspector-1", "QUALITY", "CK-A0", 422);
136	        assertEquals("PENDING_RELEASE", currentStatus(batchKey));
137	
138	        approve(batchKey, "qa-1", "QUALITY", "CK-A1", 201);
139	        // 重复角色
140	        approve(batchKey, "ops-1", "QUALITY", "CK-A2", 409);
141	        // 同一人不能完成两种角色
142	        approve(batchKey, "qa-1", "OPERATIONS", "CK-A3", 409);
143	        assertEquals("RELEASE_REVIEW", currentStatus(batchKey));
144	
145	        approve(batchKey, "ops-1", "OPERATIONS", "CK-A4", 201);
