    @Test
    void submitRoleAndHeaderValidation_return400() throws Exception {
        String root = "BK-DR-R-" + unique();
        buildRecalledTree(root, List.of(new String[]{"BK-DR-C1-" + unique(), "L1"},
                new String[]{"BK-DR-C2-" + unique(), "L2"}), true);
