        reject(dKey, "ops", "OPERATIONS", rejectBody("REQ-CS-RJ-" + unique(), "重提"), 200);
        frozen = submitAndFreeze(root, "DP-CSL2-" + unique(), allHold(closure));
        dKey = dispositionKeyOf(frozen);
