    /** 供版本错误用例以路径变量动态指定处置单（当前未使用，保留显式 409 校验入口）。 */
    private MvcResult confirm(java.util.function.Function<String, String> keyFn, JsonNode frozen,
                              String actor, String requestId, int expectedVersion,
                              List<Map<String, Object>> versions, int expected, boolean used)
